import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {demoPalette} from './palette.js';
const $=id=>document.getElementById(id);
// 原图、3D与制作图使用同一份48×48小花网格，展示真实对应关系。
const n=48,cells=Array(n*n).fill(-1);
for(let y=0;y<n;y++)for(let x=0;x<n;x++){let v=-1;if(x>=23&&x<=25&&y>=22&&y<=42)v=15;if(((x-18)/7)**2+((y-33)/3)**2<1&&x<24)v=14;if(((x-30)/6)**2+((y-36)/3)**2<1&&x>24)v=14;for(let k=0;k<6;k++){let a=k*Math.PI/3,px=24+8*Math.cos(a),py=18+8*Math.sin(a);if((x-px)**2+(y-py)**2<29)v=1}if((x-24)**2+(y-18)**2<24)v=3;cells[y*n+x]=v}
function diagram(grid=false){const c=document.createElement('canvas');c.width=c.height=576;const ctx=c.getContext('2d');ctx.fillStyle='#272727';ctx.fillRect(0,0,576,576);cells.forEach((v,i)=>{const x=i%n*12,y=Math.floor(i/n)*12;if(v>=0){ctx.fillStyle=demoPalette[v].hex;ctx.fillRect(x,y,12,12);if(grid){ctx.fillStyle='#f2f2f2';ctx.font='5px sans-serif';ctx.textAlign='center';ctx.fillText(demoPalette[v].id,x+6,y+8)}}if(grid){ctx.strokeStyle='#666666';ctx.lineWidth=.4;ctx.strokeRect(x,y,12,12)}});return c.toDataURL()}
$('inputExample').src=diagram();$('outputExample').src=diagram(true);$('largeExample').src=diagram();
try{const container=$('hero3d'),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,500),renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0,0);container.append(renderer.domElement);scene.add(new THREE.HemisphereLight(0xffffff,0xb7bcb6,1.35));let light=new THREE.DirectionalLight(0xffffff,1.25);light.position.set(-40,80,30);scene.add(light);let shape=new THREE.Shape();shape.absarc(0,0,.44,0,Math.PI*2,false);let hole=new THREE.Path();hole.absarc(0,0,.19,0,Math.PI*2,true);shape.holes.push(hole);let geom=new THREE.ExtrudeGeometry(shape,{depth:.65,bevelEnabled:true,bevelSegments:1,steps:1,bevelSize:.045,bevelThickness:.045,curveSegments:12});geom.rotateX(-Math.PI/2);let beads=new THREE.InstancedMesh(geom,new THREE.MeshLambertMaterial(),cells.filter(v=>v>=0).length),m=new THREE.Matrix4(),j=0;cells.forEach((v,i)=>{if(v<0)return;m.makeTranslation(i%n-23.5,.05,Math.floor(i/n)-23.5);beads.setMatrixAt(j,m);beads.setColorAt(j,new THREE.Color(demoPalette[v].hex));j++});scene.add(beads);let board=new THREE.Mesh(new THREE.BoxGeometry(51,.3,51),new THREE.MeshLambertMaterial({color:0x313131}));board.position.y=-.3;scene.add(board);let controls=new OrbitControls(camera,renderer.domElement);controls.enablePan=false;controls.enableZoom=false;controls.maxPolarAngle=Math.PI*.46;controls.enableDamping=true;function reset(){camera.position.set(8,67,44);controls.target.set(0,0,0);controls.update()}$('previewReset').onclick=reset;reset();new ResizeObserver(()=>{if(!container.clientWidth||!container.clientHeight)return;camera.aspect=container.clientWidth/container.clientHeight;camera.updateProjectionMatrix();renderer.setSize(container.clientWidth,container.clientHeight)}).observe(container);let visible=true;new IntersectionObserver(([e])=>{visible=e.isIntersecting}).observe(container);renderer.setAnimationLoop(()=>{if(!visible||document.hidden)return;controls.update();renderer.render(scene,camera)})}catch{const image=document.createElement('img');image.src=diagram();image.alt='小花拼豆图案；当前设备无法显示3D';image.style.cssText='width:100%;height:100%;object-fit:contain';$('hero3d').replaceChildren(image);$('previewReset').disabled=true}

let previewMode='3d';
document.querySelectorAll('[data-preview]').forEach(button=>button.addEventListener('click',()=>{previewMode=button.dataset.preview;document.querySelectorAll('[data-preview]').forEach(b=>{b.classList.toggle('is-active',b===button);b.setAttribute('aria-pressed',String(b===button))});const is3d=previewMode==='3d';$('hero3d').hidden=!is3d;$('largeExample').hidden=is3d;if(!is3d){$('largeExample').src=previewMode==='chart'?diagram(true):diagram();$('largeExample').alt=previewMode==='chart'?'同一朵小花的带网格色号制作图':'小花像素原图示例'}$('previewHint').textContent=is3d?'拖动旋转 · 感受颗粒与厚度':previewMode==='chart'?'带网格与色号 · 对照制作':'原始像素图 · 与预览使用相同颜色';$('previewReset').hidden=!is3d}));
const menuToggle=$('menuToggle'),shell=document.querySelector('.nav-shell');
function closeMenu(){shell.classList.remove('menu-open');document.body.classList.remove('menu-open');menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','打开导航');document.querySelector('main').inert=false;document.querySelector('footer').inert=false}
menuToggle.onclick=()=>{const open=shell.classList.toggle('menu-open');document.body.classList.toggle('menu-open',open);menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'关闭导航':'打开导航');document.querySelector('main').inert=open;document.querySelector('footer').inert=open;if(open)document.querySelector('#mainNav a').focus()};
document.querySelectorAll('#mainNav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduce&&'IntersectionObserver' in window){const reveal=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-revealed');reveal.unobserve(e.target)}})},{threshold:.12});document.querySelectorAll('.section-heading,.benefits article,.process li,.questions article,.statement,.closing').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',(i%3)*60+'ms');reveal.observe(el)})}

matchMedia('(min-width: 601px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
